import { computed, effect, Injectable, inject, Injector, signal } from '@angular/core';
import { TmdbMovie, WatchItem } from './movie';

@Injectable({ providedIn: 'root' })
export class WatchlistStore {
    private readonly KEY = 'watchlist';

    private parseStoredItems(): WatchItem[] {
        const raw = localStorage.getItem(this.KEY);
        if (!raw) return [];
        try {
            const parsed = JSON.parse(raw);
            return Array.isArray(parsed) ? parsed : [];
        } catch {
            return [];
        }
    }

    private _items = signal<WatchItem[]>(this.parseStoredItems());

    items = this._items.asReadonly();
    count = computed(() => this._items().length);
    watchedCount = computed(() => this._items().filter(m => m.watched).length);

    constructor() {
        try {
            const injector = inject(Injector);
            effect(() => {
                localStorage.setItem(this.KEY, JSON.stringify(this._items()));
            }, { injector });
        } catch {
            // Created outside an injection context: skip persistence effect
            // (avoids NG0203). State still works in-memory.
        }
    }

    add(movie: TmdbMovie) {
        this._items.update(items =>
            items.some(m => m.id === movie.id)
                ? items
                : [...items, { id: movie.id, title: movie.title, poster_path: movie.poster_path, release_date: movie.release_date, watched: false }]
        );
    }

    remove(id: number) {
        this._items.update(items => items.filter(m => m.id !== id));
    }

    toggleWatched(id: number) {
        this._items.update(items =>
            items.map(m => m.id === id ? { ...m, watched: !m.watched } : m)
        );
    }

    clearWatched(): void {
        this._items.update(items => (items ?? []).filter(m => !m.watched));
    }
}

import { TestBed } from '@angular/core/testing';
import { WatchlistStore } from './watchlist-store';
import { TmdbMovie } from './movie';

describe('WatchlistStore', () => {
  let service: WatchlistStore;

  const movie = (id: number): TmdbMovie => ({
    id,
    title: `Movie ${id}`,
    release_date: '2024-01-01',
    poster_path: null,
    overview: '',
  });

  beforeEach(() => {
    localStorage.removeItem('watchlist');
    TestBed.configureTestingModule({});
    service = TestBed.inject(WatchlistStore);
  });

  it('should be created', () => {
    expect(service).toBeTruthy();
  });

  it('clearWatched removes watched items and keeps unwatched ones', () => {
    service.add(movie(1));
    service.add(movie(2));
    service.toggleWatched(2);

    service.clearWatched();

    expect(service.items().map(m => m.id)).toEqual([1]);
    expect(service.watchedCount()).toBe(0);
    expect(JSON.parse(localStorage.getItem('watchlist')!)).toEqual([
      expect.objectContaining({ id: 1, watched: false })
    ]);
  });

  it('items() is never null and keeps unwatched items after clearWatched', () => {
    localStorage.setItem('watchlist', JSON.stringify([
      { id: 1, title: 'Movie 1', watched: false },
      { id: 2, title: 'Movie 2', watched: true },
    ]));
    TestBed.resetTestingModule();
    TestBed.configureTestingModule({});
    const restored = TestBed.inject(WatchlistStore);

    expect(Array.isArray(restored.items())).toBe(true);

    restored.clearWatched();

    expect(restored.items()).not.toBeNull();
    expect(restored.items()).toEqual([
      expect.objectContaining({ id: 1, watched: false }),
    ]);
  });

  it('handles corrupted storage gracefully', () => {
    localStorage.setItem('watchlist', 'not-json');
    TestBed.resetTestingModule();
    TestBed.configureTestingModule({});
    const restored = TestBed.inject(WatchlistStore);

    expect(restored.items()).toEqual([]);
  });
});

